const config = {
  "previewFeatures": [],
  "clientVersion": "7.0.1",
  "engineVersion": "f09f2815f091dbba658cdcd2264306d88bb5bda6",
  "activeProvider": "postgresql",
  "inlineSchema": "// DirectKey Unified Production Prisma Schema\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ==========================================\n// 1. IDENTITY & ACCESS\n// ==========================================\n\nenum UserRole {\n  ADMIN\n  LANDLORD\n  AGENT\n  TENANT\n}\n\nenum UserStatus {\n  ACTIVE\n  SUSPENDED\n  PENDING_VERIFICATION\n}\n\nmodel User {\n  id              String     @id @default(uuid())\n  email           String     @unique\n  passwordHash    String\n  firstName       String\n  lastName        String\n  phone           String     @unique\n  role            UserRole   @default(TENANT)\n  status          UserStatus @default(ACTIVE)\n  isEmailVerified Boolean    @default(false)\n  isPhoneVerified Boolean    @default(false)\n  avatarUrl       String?\n  createdAt       DateTime   @default(now())\n  updatedAt       DateTime   @updatedAt\n\n  // Relationships\n  ownedProperties      Property[]           @relation(\"PropertyOwner\")\n  managedAssignments   AgentAssignment[]    @relation(\"AgentAssigned\")\n  createdAssignments   AgentAssignment[]    @relation(\"LandlordAssigner\")\n  applications         Application[]        @relation(\"ApplicantApplications\")\n  reviewedApplications Application[]        @relation(\"ReviewerApplications\")\n  reservations         Reservation[]        @relation(\"TenantReservations\")\n  tenantTenancies      Tenancy[]            @relation(\"TenantTenancies\")\n  landlordTenancies    Tenancy[]            @relation(\"LandlordTenancies\")\n  maintenanceRequests  MaintenanceRequest[] @relation(\"RequestedMaintenance\")\n  assignedMaintenance  MaintenanceRequest[] @relation(\"AssignedMaintenance\")\n  tenantIssues         TenantIssue[]        @relation(\"ReportedIssues\")\n  assignedIssues       TenantIssue[]        @relation(\"AssignedIssues\")\n  viewingRequests      ViewingRequest[]     @relation(\"TenantViewings\")\n  enquiries            Enquiry[]            @relation(\"TenantEnquiries\")\n  notifications        Notification[]       @relation(\"UserNotifications\")\n  auditLogs            AuditLog[]           @relation(\"ActorAuditLogs\")\n  recordedPayments     PaymentRecord[]      @relation(\"RecordedPayments\")\n  verifiedPayments     PaymentRecord[]      @relation(\"VerifiedPayments\")\n\n  @@index([email])\n  @@index([phone])\n  @@index([role])\n}\n\nmodel AgentAssignment {\n  id                    String   @id @default(uuid())\n  propertyId            String\n  property              Property @relation(fields: [propertyId], references: [id], onDelete: Cascade)\n  agentId               String\n  agent                 User     @relation(\"AgentAssigned\", fields: [agentId], references: [id], onDelete: Cascade)\n  assignedById          String\n  assignedBy            User     @relation(\"LandlordAssigner\", fields: [assignedById], references: [id])\n  canManageListings     Boolean  @default(true)\n  canManageApplications Boolean  @default(true)\n  canManageMaintenance  Boolean  @default(true)\n  canRecordPayments     Boolean  @default(true)\n  isActive              Boolean  @default(true)\n  createdAt             DateTime @default(now())\n  updatedAt             DateTime @updatedAt\n\n  @@unique([propertyId, agentId])\n  @@index([propertyId])\n  @@index([agentId])\n}\n\n// ==========================================\n// 2. PROPERTY & INVENTORY DOMAIN\n// ==========================================\n\nenum PropertyType {\n  APARTMENT\n  SELF_CONTAINED\n  MINI_FLAT\n  DUPLEX\n  TERRACE\n  DETACHED_HOUSE\n  SHARED_APARTMENT\n  HOSTEL\n  COMMERCIAL\n}\n\nenum VerificationStatus {\n  UNVERIFIED\n  SUBMITTED\n  UNDER_REVIEW\n  VERIFIED\n  REJECTED\n}\n\nenum InventoryStatus {\n  AVAILABLE\n  RESERVED\n  OCCUPIED\n  MAINTENANCE\n  INACTIVE\n}\n\nmodel Property {\n  id                 String             @id @default(uuid())\n  ownerId            String\n  owner              User               @relation(\"PropertyOwner\", fields: [ownerId], references: [id], onDelete: Cascade)\n  title              String\n  description        String?\n  propertyType       PropertyType       @default(APARTMENT)\n  addressStreet      String\n  area               String // e.g. \"Lekki Phase 1\", \"Yaba\", \"Ikeja GRA\"\n  city               String             @default(\"Lagos\")\n  state              String             @default(\"Lagos\")\n  postalCode         String?\n  latitude           Float?\n  longitude          Float?\n  verificationStatus VerificationStatus @default(UNVERIFIED)\n  isActive           Boolean            @default(true)\n  deletedAt          DateTime?\n  createdAt          DateTime           @default(now())\n  updatedAt          DateTime           @updatedAt\n\n  // Relationships\n  buildings         Building[]\n  units             Unit[]\n  rooms             Room[]\n  beds              Bed[]\n  media             PropertyMedia[]\n  agentAssignments  AgentAssignment[]\n  verificationCases VerificationCase[]\n  listings          Listing[]\n  tenancies         Tenancy[]\n  maintenance       MaintenanceRequest[]\n  issues            TenantIssue[]\n\n  @@index([ownerId])\n  @@index([area])\n  @@index([city])\n  @@index([verificationStatus])\n  @@index([isActive])\n}\n\nmodel Building {\n  id          String   @id @default(uuid())\n  propertyId  String\n  property    Property @relation(fields: [propertyId], references: [id], onDelete: Cascade)\n  name        String\n  description String?\n  floors      Int?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  units Unit[]\n\n  @@index([propertyId])\n}\n\nmodel Unit {\n  id             String          @id @default(uuid())\n  propertyId     String\n  property       Property        @relation(fields: [propertyId], references: [id], onDelete: Cascade)\n  buildingId     String?\n  building       Building?       @relation(fields: [buildingId], references: [id], onDelete: SetNull)\n  unitNumber     String // e.g., \"Flat 3B\", \"Unit 10\"\n  floor          Int?\n  bedrooms       Int             @default(1)\n  bathrooms      Int             @default(1)\n  sqft           Int?\n  rentAmount     Decimal         @db.Decimal(12, 2)\n  cautionDeposit Decimal         @db.Decimal(12, 2)\n  serviceCharge  Decimal         @default(0) @db.Decimal(12, 2)\n  status         InventoryStatus @default(AVAILABLE)\n  createdAt      DateTime        @default(now())\n  updatedAt      DateTime        @updatedAt\n\n  // Relationships\n  rooms        Room[]\n  media        PropertyMedia[]\n  listings     Listing[]\n  reservations Reservation[]\n  tenancies    Tenancy[]\n\n  @@unique([propertyId, unitNumber])\n  @@index([propertyId])\n  @@index([buildingId])\n  @@index([status])\n}\n\nmodel Room {\n  id             String          @id @default(uuid())\n  unitId         String\n  unit           Unit            @relation(fields: [unitId], references: [id], onDelete: Cascade)\n  propertyId     String\n  property       Property        @relation(fields: [propertyId], references: [id], onDelete: Cascade)\n  name           String // e.g., \"Master Bedroom\", \"Room A\"\n  type           String? // \"Ensuite\", \"Standard\", \"Dorm\"\n  size           Int?\n  rentAmount     Decimal         @db.Decimal(12, 2)\n  cautionDeposit Decimal         @db.Decimal(12, 2)\n  status         InventoryStatus @default(AVAILABLE)\n  createdAt      DateTime        @default(now())\n  updatedAt      DateTime        @updatedAt\n\n  beds         Bed[]\n  listings     Listing[]\n  reservations Reservation[]\n  tenancies    Tenancy[]\n\n  @@unique([unitId, name])\n  @@index([unitId])\n  @@index([propertyId])\n  @@index([status])\n}\n\nmodel Bed {\n  id             String          @id @default(uuid())\n  roomId         String\n  room           Room            @relation(fields: [roomId], references: [id], onDelete: Cascade)\n  propertyId     String\n  property       Property        @relation(fields: [propertyId], references: [id], onDelete: Cascade)\n  label          String // e.g., \"Bed 1\", \"Top Bunk\"\n  rentAmount     Decimal         @db.Decimal(12, 2)\n  cautionDeposit Decimal?        @db.Decimal(12, 2)\n  status         InventoryStatus @default(AVAILABLE)\n  createdAt      DateTime        @default(now())\n  updatedAt      DateTime        @updatedAt\n\n  listings     Listing[]\n  reservations Reservation[]\n  tenancies    Tenancy[]\n\n  @@unique([roomId, label])\n  @@index([roomId])\n  @@index([propertyId])\n  @@index([status])\n}\n\nenum MediaCategory {\n  PHOTO\n  TITLE_DOCUMENT\n  FLOOR_PLAN\n  METER\n  VIDEO_TOUR\n}\n\nmodel PropertyMedia {\n  id         String        @id @default(uuid())\n  propertyId String\n  property   Property      @relation(fields: [propertyId], references: [id], onDelete: Cascade)\n  unitId     String?\n  unit       Unit?         @relation(fields: [unitId], references: [id], onDelete: SetNull)\n  url        String\n  caption    String?\n  category   MediaCategory @default(PHOTO)\n  isCover    Boolean       @default(false)\n  createdAt  DateTime      @default(now())\n\n  @@index([propertyId])\n  @@index([unitId])\n}\n\n// ==========================================\n// 3. LISTINGS & MARKETPLACE\n// ==========================================\n\nenum ListingStatus {\n  DRAFT\n  PUBLISHED\n  RESERVED\n  LEASED\n  DELISTED\n}\n\nenum BillingFrequency {\n  MONTHLY\n  QUARTERLY\n  BI_ANNUAL\n  ANNUAL\n}\n\nmodel Listing {\n  id               String           @id @default(uuid())\n  propertyId       String\n  property         Property         @relation(fields: [propertyId], references: [id], onDelete: Cascade)\n  unitId           String?\n  unit             Unit?            @relation(fields: [unitId], references: [id], onDelete: SetNull)\n  roomId           String?\n  room             Room?            @relation(fields: [roomId], references: [id], onDelete: SetNull)\n  bedId            String?\n  bed              Bed?             @relation(fields: [bedId], references: [id], onDelete: SetNull)\n  headline         String\n  description      String\n  displayPrice     Decimal          @db.Decimal(12, 2)\n  cautionDeposit   Decimal          @db.Decimal(12, 2)\n  serviceCharge    Decimal          @default(0) @db.Decimal(12, 2)\n  billingFrequency BillingFrequency @default(ANNUAL)\n  amenities        String[]\n  photos           String[]\n  status           ListingStatus    @default(DRAFT)\n  viewsCount       Int              @default(0)\n  isFeatured       Boolean          @default(false)\n  createdAt        DateTime         @default(now())\n  updatedAt        DateTime         @updatedAt\n\n  applications      Application[]\n  viewingRequests   ViewingRequest[]\n  enquiries         Enquiry[]\n  suspiciousReports SuspiciousReport[]\n\n  @@index([propertyId])\n  @@index([status])\n  @@index([isFeatured])\n  @@index([displayPrice])\n}\n\nenum ViewingStatus {\n  PENDING\n  CONFIRMED\n  COMPLETED\n  CANCELLED\n  REJECTED\n}\n\nmodel ViewingRequest {\n  id              String        @id @default(uuid())\n  listingId       String\n  listing         Listing       @relation(fields: [listingId], references: [id], onDelete: Cascade)\n  tenantId        String\n  tenant          User          @relation(\"TenantViewings\", fields: [tenantId], references: [id])\n  preferredDate   DateTime\n  alternativeDate DateTime?\n  contactPhone    String\n  notes           String?\n  status          ViewingStatus @default(PENDING)\n  hostNotes       String?\n  confirmedDate   DateTime?\n  createdAt       DateTime      @default(now())\n  updatedAt       DateTime      @updatedAt\n\n  @@index([listingId])\n  @@index([tenantId])\n  @@index([status])\n}\n\nmodel Enquiry {\n  id        String   @id @default(uuid())\n  listingId String\n  listing   Listing  @relation(fields: [listingId], references: [id], onDelete: Cascade)\n  tenantId  String\n  tenant    User     @relation(\"TenantEnquiries\", fields: [tenantId], references: [id])\n  message   String\n  response  String?\n  status    String   @default(\"OPEN\") // OPEN, RESPONDED, CLOSED\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([listingId])\n  @@index([tenantId])\n}\n\n// ==========================================\n// 4. VERIFICATION & TRUST\n// ==========================================\n\nenum VerificationCaseCategory {\n  OWNERSHIP_DOCS\n  PHYSICAL_INSPECTION\n  IDENTITY_CHECK\n  COMBINED\n}\n\nenum VerificationCaseStatus {\n  SUBMITTED\n  UNDER_REVIEW\n  APPROVED\n  REJECTED\n  MORE_INFO_REQUIRED\n}\n\nmodel VerificationCase {\n  id              String                   @id @default(uuid())\n  propertyId      String\n  property        Property                 @relation(fields: [propertyId], references: [id], onDelete: Cascade)\n  submittedById   String\n  category        VerificationCaseCategory @default(COMBINED)\n  evidenceUrls    String[]\n  meterNumber     String?\n  gpsLatitude     Float?\n  gpsLongitude    Float?\n  ownershipDocUrl String?\n  decisionNotes   String?\n  rejectionReason String?\n  status          VerificationCaseStatus   @default(SUBMITTED)\n  reviewedById    String?\n  verifiedAt      DateTime?\n  createdAt       DateTime                 @default(now())\n  updatedAt       DateTime                 @updatedAt\n\n  @@index([propertyId])\n  @@index([status])\n}\n\nmodel SuspiciousReport {\n  id         String   @id @default(uuid())\n  listingId  String\n  listing    Listing  @relation(fields: [listingId], references: [id], onDelete: Cascade)\n  reporterId String?\n  reason     String // e.g. \"Fake Photos\", \"Unrealistic Price\", \"Already Leased\"\n  details    String?\n  status     String   @default(\"PENDING\") // PENDING, REVIEWED, DISMISSED, ACTION_TAKEN\n  adminNotes String?\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  @@index([listingId])\n  @@index([status])\n}\n\n// ==========================================\n// 5. RENTAL APPLICATIONS & RESERVATIONS\n// ==========================================\n\nenum ApplicationStatus {\n  SUBMITTED\n  UNDER_REVIEW\n  APPROVED\n  DECLINED\n  WITHDRAWN\n}\n\nmodel Application {\n  id                 String            @id @default(uuid())\n  listingId          String\n  listing            Listing           @relation(fields: [listingId], references: [id], onDelete: Cascade)\n  applicantId        String\n  applicant          User              @relation(\"ApplicantApplications\", fields: [applicantId], references: [id])\n  monthlyIncome      Decimal           @db.Decimal(12, 2)\n  employmentStatus   String // \"FULL_TIME\", \"SELF_EMPLOYED\", \"STUDENT\"\n  employerName       String\n  idDocumentUrl      String?\n  guarantorName      String?\n  guarantorPhone     String?\n  proposedMoveInDate DateTime\n  coverLetter        String?\n  status             ApplicationStatus @default(SUBMITTED)\n  reviewedById       String?\n  reviewer           User?             @relation(\"ReviewerApplications\", fields: [reviewedById], references: [id])\n  reviewedAt         DateTime?\n  decisionNotes      String?\n  createdAt          DateTime          @default(now())\n  updatedAt          DateTime          @updatedAt\n\n  offers      Offer[]\n  reservation Reservation?\n  tenancy     Tenancy?\n\n  @@index([listingId])\n  @@index([applicantId])\n  @@index([status])\n}\n\nenum OfferStatus {\n  PENDING\n  ACCEPTED\n  REJECTED\n  COUNTERED\n}\n\nmodel Offer {\n  id                   String           @id @default(uuid())\n  applicationId        String\n  application          Application      @relation(fields: [applicationId], references: [id], onDelete: Cascade)\n  agreedRent           Decimal          @db.Decimal(12, 2)\n  agreedCautionDeposit Decimal          @db.Decimal(12, 2)\n  agreedServiceCharge  Decimal          @default(0) @db.Decimal(12, 2)\n  billingFrequency     BillingFrequency @default(ANNUAL)\n  leaseDurationMonths  Int              @default(12)\n  status               OfferStatus      @default(PENDING)\n  notes                String?\n  createdAt            DateTime         @default(now())\n  updatedAt            DateTime         @updatedAt\n\n  @@index([applicationId])\n}\n\nenum ReservationStatus {\n  ACTIVE_HOLD\n  CONFIRMED\n  EXPIRED\n  CANCELLED\n}\n\nmodel Reservation {\n  id            String            @id @default(uuid())\n  unitId        String?\n  unit          Unit?             @relation(fields: [unitId], references: [id], onDelete: SetNull)\n  roomId        String?\n  room          Room?             @relation(fields: [roomId], references: [id], onDelete: SetNull)\n  bedId         String?\n  bed           Bed?              @relation(fields: [bedId], references: [id], onDelete: SetNull)\n  applicationId String?           @unique\n  application   Application?      @relation(fields: [applicationId], references: [id], onDelete: SetNull)\n  tenantId      String\n  tenant        User              @relation(\"TenantReservations\", fields: [tenantId], references: [id])\n  expiresAt     DateTime // Timestamp when the temporary hold expires\n  status        ReservationStatus @default(ACTIVE_HOLD)\n  holdFeeAmount Decimal?          @db.Decimal(12, 2)\n  holdFeePaid   Boolean           @default(false)\n  createdAt     DateTime          @default(now())\n  updatedAt     DateTime          @updatedAt\n\n  tenancy Tenancy?\n\n  @@index([unitId, status])\n  @@index([roomId, status])\n  @@index([bedId, status])\n  @@index([expiresAt])\n  @@index([tenantId])\n}\n\n// ==========================================\n// 6. TENANCY MANAGEMENT & AGREEMENTS\n// ==========================================\n\nenum TenancyStatus {\n  PENDING\n  ACTIVE\n  RENEWAL_PENDING\n  COMPLETED\n  TERMINATED\n  CANCELLED\n}\n\nmodel Tenancy {\n  id            String       @id @default(uuid())\n  propertyId    String\n  property      Property     @relation(fields: [propertyId], references: [id])\n  unitId        String?\n  unit          Unit?        @relation(fields: [unitId], references: [id])\n  roomId        String?\n  room          Room?        @relation(fields: [roomId], references: [id])\n  bedId         String?\n  bed           Bed?         @relation(fields: [bedId], references: [id])\n  tenantId      String\n  tenant        User         @relation(\"TenantTenancies\", fields: [tenantId], references: [id])\n  landlordId    String\n  landlord      User         @relation(\"LandlordTenancies\", fields: [landlordId], references: [id])\n  applicationId String?      @unique\n  application   Application? @relation(fields: [applicationId], references: [id])\n  reservationId String?      @unique\n  reservation   Reservation? @relation(fields: [reservationId], references: [id])\n\n  // Tenancy Dates\n  startDate          DateTime\n  endDate            DateTime\n  propertyReadyDate  DateTime?\n  actualHandoverDate DateTime?\n  commencementDate   DateTime?\n  actualMoveOutDate  DateTime?\n\n  // Financial Terms\n  rentAmount       Decimal          @db.Decimal(12, 2)\n  cautionDeposit   Decimal          @db.Decimal(12, 2)\n  serviceCharge    Decimal          @default(0) @db.Decimal(12, 2)\n  billingFrequency BillingFrequency @default(ANNUAL)\n  rentDueDay       Int? // 1-31\n  gracePeriodDays  Int              @default(5)\n  lateFeeAmount    Decimal          @default(0) @db.Decimal(12, 2)\n\n  status            TenancyStatus @default(PENDING)\n  terminationReason String?\n  createdAt         DateTime      @default(now())\n  updatedAt         DateTime      @updatedAt\n\n  // Relationships\n  occupants           TenancyOccupant[]\n  agreements          TenancyAgreement[]\n  obligations         RentObligation[]\n  paymentRecords      PaymentRecord[]\n  paymentInstructions PaymentInstruction[]\n  maintenanceRequests MaintenanceRequest[]\n  tenantIssues        TenantIssue[]\n  handovers           HandoverInspection[]\n\n  @@index([propertyId])\n  @@index([tenantId])\n  @@index([landlordId])\n  @@index([status])\n}\n\nmodel TenancyOccupant {\n  id           String   @id @default(uuid())\n  tenancyId    String\n  tenancy      Tenancy  @relation(fields: [tenancyId], references: [id], onDelete: Cascade)\n  fullName     String\n  phone        String?\n  relationship String? // \"Spouse\", \"Child\", \"Roommate\"\n  isPrimary    Boolean  @default(false)\n  createdAt    DateTime @default(now())\n\n  @@index([tenancyId])\n}\n\nenum AgreementStatus {\n  DRAFT\n  PENDING_SIGNATURES\n  TENANT_SIGNED\n  LANDLORD_SIGNED\n  FULLY_EXECUTED\n  TERMINATED\n}\n\nmodel TenancyAgreement {\n  id               String          @id @default(uuid())\n  tenancyId        String\n  tenancy          Tenancy         @relation(fields: [tenancyId], references: [id], onDelete: Cascade)\n  version          Int             @default(1)\n  documentUrl      String?\n  documentHash     String? // SHA-256 integrity hash\n  termsContent     String? // Text or HTML template\n  status           AgreementStatus @default(DRAFT)\n  tenantSignedAt   DateTime?\n  tenantSignIp     String?\n  landlordSignedAt DateTime?\n  landlordSignIp   String?\n  createdAt        DateTime        @default(now())\n  updatedAt        DateTime        @updatedAt\n\n  @@index([tenancyId])\n  @@index([status])\n}\n\n// ==========================================\n// 7. RENT & PAYMENTS (NO ESCROW)\n// ==========================================\n\nenum ObligationType {\n  RENT\n  CAUTION_DEPOSIT\n  SERVICE_CHARGE\n  LATE_FEE\n  OTHER\n}\n\nenum ObligationStatus {\n  PENDING\n  PARTIALLY_PAID\n  PAID\n  OVERDUE\n  WAIVED\n}\n\nmodel RentObligation {\n  id               String           @id @default(uuid())\n  tenancyId        String\n  tenancy          Tenancy          @relation(fields: [tenancyId], references: [id], onDelete: Cascade)\n  obligationType   ObligationType   @default(RENT)\n  dueDate          DateTime\n  periodStart      DateTime\n  periodEnd        DateTime\n  amountDue        Decimal          @db.Decimal(12, 2)\n  amountPaid       Decimal          @default(0) @db.Decimal(12, 2)\n  balanceRemaining Decimal          @db.Decimal(12, 2)\n  status           ObligationStatus @default(PENDING)\n  description      String?\n  createdAt        DateTime         @default(now())\n  updatedAt        DateTime         @updatedAt\n\n  payments PaymentRecord[]\n\n  @@index([tenancyId])\n  @@index([dueDate])\n  @@index([status])\n}\n\nenum PaymentMethod {\n  BANK_TRANSFER\n  CARD\n  DIRECT_DEPOSIT\n  CASH\n  OTHER\n}\n\nenum PaymentVerificationStatus {\n  REPORTED\n  VERIFIED\n  REJECTED\n  DISPUTED\n}\n\nmodel PaymentRecord {\n  id                 String                    @id @default(uuid())\n  tenancyId          String\n  tenancy            Tenancy                   @relation(fields: [tenancyId], references: [id], onDelete: Cascade)\n  obligationId       String?\n  obligation         RentObligation?           @relation(fields: [obligationId], references: [id], onDelete: SetNull)\n  recordedById       String\n  recordedBy         User                      @relation(\"RecordedPayments\", fields: [recordedById], references: [id])\n  amount             Decimal                   @db.Decimal(12, 2)\n  currency           String                    @default(\"NGN\")\n  paymentDate        DateTime\n  paymentMethod      PaymentMethod             @default(BANK_TRANSFER)\n  bankName           String?\n  accountNumber      String?\n  providerReference  String? // Bank teller / gateway transaction ref\n  evidenceUrl        String? // Receipt or transfer receipt screenshot\n  notes              String?\n  verificationStatus PaymentVerificationStatus @default(REPORTED)\n  verifiedById       String?\n  verifiedBy         User?                     @relation(\"VerifiedPayments\", fields: [verifiedById], references: [id])\n  verifiedAt         DateTime?\n  rejectionReason    String?\n  createdAt          DateTime                  @default(now())\n  updatedAt          DateTime                  @updatedAt\n\n  corrections PaymentCorrection[]\n\n  @@index([tenancyId])\n  @@index([obligationId])\n  @@index([providerReference])\n  @@index([verificationStatus])\n}\n\nmodel PaymentInstruction {\n  id                String   @id @default(uuid())\n  tenancyId         String\n  tenancy           Tenancy  @relation(fields: [tenancyId], references: [id], onDelete: Cascade)\n  bankName          String\n  accountNumber     String\n  accountName       String\n  instructions      String?\n  referenceTemplate String? // e.g. \"DK-TEN-{tenancyId}\"\n  isActive          Boolean  @default(true)\n  createdAt         DateTime @default(now())\n  updatedAt         DateTime @updatedAt\n\n  @@index([tenancyId])\n}\n\nmodel PaymentCorrection {\n  id              String        @id @default(uuid())\n  paymentRecordId String\n  paymentRecord   PaymentRecord @relation(fields: [paymentRecordId], references: [id], onDelete: Cascade)\n  previousAmount  Decimal       @db.Decimal(12, 2)\n  correctedAmount Decimal       @db.Decimal(12, 2)\n  reason          String\n  authorizedById  String\n  createdAt       DateTime      @default(now())\n\n  @@index([paymentRecordId])\n}\n\n// ==========================================\n// 8. MAINTENANCE REQUESTS\n// ==========================================\n\nenum MaintenanceCategory {\n  PLUMBING\n  ELECTRICAL\n  STRUCTURAL\n  APPLIANCE\n  CARPENTRY\n  PAINTING\n  SECURITY\n  OTHER\n}\n\nenum MaintenanceUrgency {\n  LOW\n  MEDIUM\n  HIGH\n  EMERGENCY\n}\n\nenum MaintenanceStatus {\n  SUBMITTED\n  UNDER_REVIEW\n  APPROVED\n  SCHEDULED\n  IN_PROGRESS\n  AWAITING_TENANT\n  COMPLETED\n  REJECTED\n}\n\nmodel MaintenanceRequest {\n  id               String              @id @default(uuid())\n  propertyId       String\n  property         Property            @relation(fields: [propertyId], references: [id], onDelete: Cascade)\n  tenancyId        String?\n  tenancy          Tenancy?            @relation(fields: [tenancyId], references: [id], onDelete: SetNull)\n  requesterId      String\n  requester        User                @relation(\"RequestedMaintenance\", fields: [requesterId], references: [id])\n  assignedToId     String?\n  assignedTo       User?               @relation(\"AssignedMaintenance\", fields: [assignedToId], references: [id])\n  title            String\n  description      String\n  category         MaintenanceCategory @default(OTHER)\n  urgency          MaintenanceUrgency  @default(MEDIUM)\n  status           MaintenanceStatus   @default(SUBMITTED)\n  accessPreference String? // \"Anytime\", \"Morning only\", \"Evenings\"\n  estimatedCost    Decimal?            @db.Decimal(10, 2)\n  actualCost       Decimal?            @db.Decimal(10, 2)\n  scheduledFor     DateTime?\n  completedAt      DateTime?\n  rejectionReason  String?\n  createdAt        DateTime            @default(now())\n  updatedAt        DateTime            @updatedAt\n\n  comments    MaintenanceComment[]\n  attachments MaintenanceAttachment[]\n  statusLogs  MaintenanceStatusLog[]\n\n  @@index([propertyId])\n  @@index([tenancyId])\n  @@index([requesterId])\n  @@index([assignedToId])\n  @@index([status])\n}\n\nmodel MaintenanceComment {\n  id                   String             @id @default(uuid())\n  maintenanceRequestId String\n  maintenanceRequest   MaintenanceRequest @relation(fields: [maintenanceRequestId], references: [id], onDelete: Cascade)\n  authorId             String\n  message              String\n  isInternal           Boolean            @default(false)\n  createdAt            DateTime           @default(now())\n\n  @@index([maintenanceRequestId])\n}\n\nmodel MaintenanceAttachment {\n  id                   String             @id @default(uuid())\n  maintenanceRequestId String\n  maintenanceRequest   MaintenanceRequest @relation(fields: [maintenanceRequestId], references: [id], onDelete: Cascade)\n  url                  String\n  caption              String?\n  uploadedById         String\n  createdAt            DateTime           @default(now())\n\n  @@index([maintenanceRequestId])\n}\n\nmodel MaintenanceStatusLog {\n  id                   String             @id @default(uuid())\n  maintenanceRequestId String\n  maintenanceRequest   MaintenanceRequest @relation(fields: [maintenanceRequestId], references: [id], onDelete: Cascade)\n  fromStatus           MaintenanceStatus\n  toStatus             MaintenanceStatus\n  changedById          String\n  note                 String?\n  createdAt            DateTime           @default(now())\n\n  @@index([maintenanceRequestId])\n}\n\n// ==========================================\n// 9. TENANT ISSUES & DISPUTES\n// ==========================================\n\nenum IssueCategory {\n  NOISE_DISTURBANCE\n  NEIGHBOR_DISPUTE\n  HARASSMENT\n  BILLING_DISAGREEMENT\n  LEASE_VIOLATION\n  PROPERTY_CONDITION\n  SECURITY_CONCERN\n  OTHER\n}\n\nenum IssuePriority {\n  LOW\n  MEDIUM\n  HIGH\n  URGENT\n}\n\nenum IssueStatus {\n  OPEN\n  UNDER_REVIEW\n  IN_DISCUSSION\n  ESCALATED\n  RESOLVED\n  DISMISSED\n}\n\nmodel TenantIssue {\n  id              String        @id @default(uuid())\n  propertyId      String\n  property        Property      @relation(fields: [propertyId], references: [id], onDelete: Cascade)\n  tenancyId       String?\n  tenancy         Tenancy?      @relation(fields: [tenancyId], references: [id], onDelete: SetNull)\n  reporterId      String\n  reporter        User          @relation(\"ReportedIssues\", fields: [reporterId], references: [id])\n  assignedToId    String?\n  assignedTo      User?         @relation(\"AssignedIssues\", fields: [assignedToId], references: [id])\n  category        IssueCategory @default(OTHER)\n  priority        IssuePriority @default(MEDIUM)\n  title           String\n  description     String\n  evidenceUrls    String[]\n  status          IssueStatus   @default(OPEN)\n  resolutionNotes String?\n  resolvedById    String?\n  resolvedAt      DateTime?\n  createdAt       DateTime      @default(now())\n  updatedAt       DateTime      @updatedAt\n\n  comments  TenantIssueComment[]\n  auditLogs TenantIssueAuditLog[]\n\n  @@index([propertyId])\n  @@index([tenancyId])\n  @@index([reporterId])\n  @@index([status])\n}\n\nmodel TenantIssueComment {\n  id            String      @id @default(uuid())\n  tenantIssueId String\n  tenantIssue   TenantIssue @relation(fields: [tenantIssueId], references: [id], onDelete: Cascade)\n  authorId      String\n  comment       String\n  isPrivate     Boolean     @default(false) // Admin / Agent internal note\n  createdAt     DateTime    @default(now())\n\n  @@index([tenantIssueId])\n}\n\nmodel TenantIssueAuditLog {\n  id            String      @id @default(uuid())\n  tenantIssueId String\n  tenantIssue   TenantIssue @relation(fields: [tenantIssueId], references: [id], onDelete: Cascade)\n  action        String // e.g. \"STATUS_CHANGE\", \"ESCALATED\", \"ASSIGNED\"\n  performedById String\n  details       String?\n  createdAt     DateTime    @default(now())\n\n  @@index([tenantIssueId])\n}\n\n// ==========================================\n// 10. INSPECTIONS & HANDOVER\n// ==========================================\n\nenum HandoverType {\n  MOVE_IN\n  MOVE_OUT\n}\n\nenum HandoverStatus {\n  SCHEDULED\n  IN_PROGRESS\n  COMPLETED\n  DISPUTED\n  CANCELLED\n}\n\nenum ConditionRating {\n  EXCELLENT\n  GOOD\n  FAIR\n  POOR\n}\n\nmodel HandoverInspection {\n  id                  String          @id @default(uuid())\n  tenancyId           String\n  tenancy             Tenancy         @relation(fields: [tenancyId], references: [id], onDelete: Cascade)\n  type                HandoverType    @default(MOVE_IN)\n  scheduledDate       DateTime\n  completedDate       DateTime?\n  inspectorId         String?\n  tenantConfirmed     Boolean         @default(false)\n  tenantConfirmedAt   DateTime?\n  landlordConfirmed   Boolean         @default(false)\n  landlordConfirmedAt DateTime?\n  keysHandedCount     Int             @default(0)\n  meterReadings       Json? // e.g. { \"electricity\": \"4921 kWh\", \"water\": \"104 m3\" }\n  overallCondition    ConditionRating @default(GOOD)\n  status              HandoverStatus  @default(SCHEDULED)\n  releaseOtp          String // 6-digit confirmation PIN\n  notes               String?\n  createdAt           DateTime        @default(now())\n  updatedAt           DateTime        @updatedAt\n\n  items InspectionItem[]\n\n  @@index([tenancyId])\n  @@index([status])\n}\n\nenum ItemCondition {\n  PASS\n  FAIL\n  NEEDS_REPAIR\n  NOT_APPLICABLE\n}\n\nmodel InspectionItem {\n  id                   String             @id @default(uuid())\n  handoverInspectionId String\n  handoverInspection   HandoverInspection @relation(fields: [handoverInspectionId], references: [id], onDelete: Cascade)\n  area                 String // \"Living Room\", \"Kitchen\", \"Master Bedroom\"\n  item                 String // \"Light fixtures\", \"Faucets\", \"Walls\", \"Locks\"\n  condition            ItemCondition      @default(PASS)\n  notes                String?\n  photoUrls            String[]\n  createdAt            DateTime           @default(now())\n\n  @@index([handoverInspectionId])\n}\n\n// ==========================================\n// 11. NOTIFICATIONS\n// ==========================================\n\nenum NotificationType {\n  RENT_DUE\n  PAYMENT_UPDATE\n  APPLICATION_UPDATE\n  MAINTENANCE_UPDATE\n  ISSUE_UPDATE\n  VIEWING_UPDATE\n  AGREEMENT_READY\n  HANDOVER_UPDATE\n  SYSTEM\n}\n\nenum DeliveryChannel {\n  IN_APP\n  EMAIL\n  SMS\n}\n\nenum DeliveryStatus {\n  PENDING\n  DELIVERED\n  FAILED\n}\n\nmodel Notification {\n  id              String           @id @default(uuid())\n  recipientId     String\n  recipient       User             @relation(\"UserNotifications\", fields: [recipientId], references: [id], onDelete: Cascade)\n  title           String\n  message         String\n  type            NotificationType @default(SYSTEM)\n  actionUrl       String?\n  isRead          Boolean          @default(false)\n  readAt          DateTime?\n  deliveryChannel DeliveryChannel  @default(IN_APP)\n  deliveryStatus  DeliveryStatus   @default(DELIVERED)\n  createdAt       DateTime         @default(now())\n  updatedAt       DateTime         @updatedAt\n\n  @@index([recipientId, isRead])\n  @@index([type])\n}\n\n// ==========================================\n// 12. AUDIT TRAIL\n// ==========================================\n\nmodel AuditLog {\n  id          String   @id @default(uuid())\n  actorId     String?\n  actor       User?    @relation(\"ActorAuditLogs\", fields: [actorId], references: [id], onDelete: SetNull)\n  action      String // e.g. \"PROPERTY_VERIFIED\", \"TENANCY_TERMINATED\", \"RESERVATION_RELEASED\"\n  entityType  String // e.g. \"Property\", \"Tenancy\", \"PaymentRecord\"\n  entityId    String\n  detailsJson Json?\n  ipAddress   String?\n  userAgent   String?\n  createdAt   DateTime @default(now())\n\n  @@index([actorId])\n  @@index([entityType, entityId])\n  @@index([action])\n}\n"
}

